WITH valid AS (SELECT *, COALESCE(city, 'N/A') AS city_filled, COALESCE(city, 'NONE') AS city_filled_2 FROM suppliers WHERE city IS NOT NULL AND supplier_name LIKE '%Trad%') SELECT country, ROUND(SUM(rating) / NULLIF(COUNT(CASE WHEN country = 'US' THEN 1 END), 0), 2) AS rating_per_us, PERCENTILE_APPROX(rating, 0.95) AS rating_p95, ROUND(SUM(rating) / NULLIF(COUNT(CASE WHEN city = 'Bangkok' THEN 1 END), 0), 2) AS rating_per_bangkok, SUM(CASE WHEN city = 'Chiang Mai' THEN rating ELSE 0 END) AS chiang_mai_rating FROM valid GROUP BY country HAVING rating_per_us < 0;
